import pytest

def test_r3_accessibility():
    from glom import (Assign, Call, Check, Coalesce, Fill, First, Flatten,
                      Fold, Invoke, Iter, Let, Literal, Path, Spec, Sum,
                      UnregisteredTarget, format_invocation, kwarg_fmt)
    assert Call is not None
    assert Sum is not None

def test_r3_assign():
    from glom import glom, Assign
    target = {'a': 1}
    result = glom(target, Assign('a', 2))
    assert result == {'a': 2}

def test_r3_call():
    from glom import glom, Call
    result = glom(1, Call(lambda x: x+1))
    assert result == 2

def test_r3_check():
    from glom import glom, Check, T, CheckError
    target = 5
    result = glom(target, Check(T, type=int))
    assert result == 5
    with pytest.raises(CheckError):
        glom(target, Check(T, type=str))

def test_r3_flatten():
    from glom import glom, Flatten
    target = [[1, 2], [3]]
    result = glom(target, Flatten())
    assert result == [1, 2, 3]

def test_r3_sum():
    from glom import glom, Sum
    result = glom([1, 2, 3], Sum())
    assert result == 6

def test_r3_format_invocation():
    from glom import format_invocation
    result = format_invocation('test', args=(1,2), kwargs={'a':3})
    assert isinstance(result, str)

def test_r3_kwarg_fmt():
    from glom import kwarg_fmt
    result = kwarg_fmt(a=1, b=2)
    assert isinstance(result, str)
